actor Counter {
    private var value = 0
    func increment() { value += 1 }
}

func update(_ counter: Counter) async {
    await counter.increment()
}

func greeting() async -> String {
    "Hello"
}

func makeMessage() async -> String {
    let text = await greeting()
    return text
}

func pair() async -> (Int, Int) {
    async let first = loadValue()
    async let second = loadValue()
    return await (first, second)
}

func loadValue() async -> Int { 1 }

func process(_ values: [Int]) async throws -> Int {
    var total = 0
    for value in values {
        try Task.checkCancellation()
        total += value
    }
    return total
}

@MainActor
final class ScreenState {
    var title = "Ready"
    func updateTitle(_ value: String) { title = value }
}
